import java.util.Arrays;

public class ArrayUtils {
    /** 
     * <p>Checks whether two arrays are the same length, treating <code>null</code> arrays as length <code>0</code>.</p>
     * @param array1 the first array, may be <code>null</code>
     * @param array2 the second array, may be <code>null</code>
     * @return <code>true</code> if length of arrays matches, treating<code>null</code> as an empty array
     */
    public static boolean isSameLength(final byte[] array1, final byte[] array2) {
        int length1 = (array1 == null) ? 0 : array1.length;
        int length2 = (array2 == null) ? 0 : array2.length;
        return length1 == length2;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(isSameLength(null, null)); // true
        System.out.println(isSameLength(new byte[]{}, new byte[]{})); // true
        System.out.println(isSameLength(new byte[]{1, 2, 3}, new byte[]{4, 5, 6})); // true
        System.out.println(isSameLength(new byte[]{1, 2}, new byte[]{3, 4, 5})); // false
        System.out.println(isSameLength(null, new byte[]{})); // true
        System.out.println(isSameLength(new byte[]{1}, null)); // false
    }
}
