import java.util.Objects;

public class BooleanArrayConverter {

    /** 
     * <p>Converts an array of object Booleans to primitives.</p> <p>This method returns <code>null</code> for a <code>null</code> input array.</p>
     * @param array  a <code>Boolean</code> array, may be <code>null</code>
     * @return a <code>boolean</code> array, <code>null</code> if null array input
     * @throws NullPointerException if array content is <code>null</code>
     */
    public static boolean[] toPrimitive(final Boolean[] array) {
        if (array == null) {
            return null;
        }
        final boolean[] result = new boolean[array.length];
        for (int i = 0; i < array.length; i++) {
            result[i] = Objects.requireNonNull(array[i], "Array content cannot be null");
        }
        return result;
    }

    public static void main(String[] args) {
        Boolean[] booleanObjects = {Boolean.TRUE, Boolean.FALSE, Boolean.TRUE};
        boolean[] primitiveBooleans = toPrimitive(booleanObjects);
        for (boolean b : primitiveBooleans) {
            System.out.println(b);
        }
    }
}
