import java.nio.charset.StandardCharsets;

public class HeaderParser {

    /** 
     * Skips bytes until the end of the current line.
     * @param headerPart The headers, which are being parsed.
     * @param end Index of the last byte, which has yet been processed.
     * @return Index of the \r\n sequence, which indicates end of line.
     */
    private int parseEndOfLine(String headerPart, int end) {
        byte[] bytes = headerPart.getBytes(StandardCharsets.UTF_8);
        for (int i = end; i < bytes.length - 1; i++) {
            if (bytes[i] == '\r' && bytes[i + 1] == '\n') {
                return i;
            }
        }
        return -1; // Return -1 if no \r\n sequence is found
    }

    public static void main(String[] args) {
        HeaderParser parser = new HeaderParser();
        String header = "Header1: value1\r\nHeader2: value2\r\n";
        int index = parser.parseEndOfLine(header, 0);
        System.out.println("End of line index: " + index);
    }
}
