import org.jgrapht.alg.isomorphism.VF2GraphIsomorphismInspector;
import java.util.HashMap;
import java.util.Map;

public class GraphUtils {

    /** 
     * Computes an identity automorphism (i.e. a self-mapping of a graph in which each vertex also maps to itself).
     * @param graph the input graph
     * @param < V > the graph vertex type
     * @param < E > the graph edge type
     * @return a mapping from graph to graph
     */
    public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
        Map<V, V> vertexMap = new HashMap<>();
        for (V vertex : graph.vertexSet()) {
            vertexMap.put(vertex, vertex);
        }
        return new IsomorphicGraphMapping<>(vertexMap, graph, graph);
    }

    public static void main(String[] args) {
        // Example usage
        // Create a sample graph and test the identity method
        org.jgrapht.Graph<String, DefaultEdge> g = new org.jgrapht.graph.SimpleGraph<>(DefaultEdge.class);
        g.addVertex("v1");
        g.addVertex("v2");
        g.addVertex("v3");
        g.addEdge("v1", "v2");
        g.addEdge("v2", "v3");

        IsomorphicGraphMapping<String, DefaultEdge> identityMapping = identity(g);
        System.out.println("Identity Mapping: " + identityMapping);
    }
