import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;

public class TypeResolver {

    public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
        if (genericType instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) genericType;
            Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
            Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];

            for (int i = 0; i < actualTypeArguments.length; i++) {
                Type typeArgument = actualTypeArguments[i];
                if (typeArgument instanceof Class) {
                    resolvedArguments[i] = (Class<?>) typeArgument;
                } else if (typeArgument instanceof TypeVariable) {
                    TypeVariable<?> typeVariable = (TypeVariable<?>) typeArgument;
                    resolvedArguments[i] = resolveTypeVariable(typeVariable, targetType);
                } else {
                    return null; // Cannot resolve the type argument
                }
            }
            return resolvedArguments;
        }
        return null; // Not a parameterized type
    }

    private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
        TypeVariable<?>[] typeParameters = targetType.getTypeParameters();
        for (int i = 0; i < typeParameters.length; i++) {
            if (typeVariable.getName().equals(typeParameters[i].getName())) {
                Type[] bounds = typeVariable.getBounds();
                if (bounds.length > 0 && bounds[0] instanceof Class) {
                    return (Class<?>) bounds[0];
                }
            }
        }
        return null; // Cannot resolve the type variable
    }

    public static void main(String[] args) {
        // Example usage
        Type genericType = new ParameterizedType() {
            @Override
            public Type[] getActualTypeArguments() {
                return new Type[]{String.class, Integer.class};
            }

            @Override
            public Type getRawType() {
                return Object.class;
            }

            @Override
            public Type getOwnerType() {
                return null;
            }
        };

        Class<?>[] resolvedArguments = resolveArguments(genericType, Object.class);
        if (resolvedArguments != null) {
            for (Class<?> clazz : resolvedArguments) {
                System.out.println(clazz.getName());
            }
        } else {
            System.out.println("Arguments could not be resolved.");
        }
    }
}
