class Bucket {
    private int value;
    private Bucket next;

    public Bucket(int value) {
        this.value = value;
    }

    public Bucket getNext() {
        return next;
    }

    public void setNext(Bucket next) {
        this.next = next;
    }

    public int getValue() {
        return value;
    }
}

public class BucketList {
    private Bucket head;

    public void insertBefore(Bucket bucket) {
        if (head == null || bucket == null) {
            return;
        }

        if (head == bucket) {
            // If the bucket to insert before is the head, do nothing as there's no previous bucket
            return;
        }

        Bucket current = head;
        while (current.getNext() != null && current.getNext() != bucket) {
            current = current.getNext();
        }

        if (current.getNext() == bucket) {
            Bucket newBucket = new Bucket(bucket.getValue());
            newBucket.setNext(bucket);
            current.setNext(newBucket);
        }
    }

    public static void main(String[] args) {
        BucketList list = new BucketList();
        Bucket bucket1 = new Bucket(1);
        Bucket bucket2 = new Bucket(2);
        Bucket bucket3 = new Bucket(3);

        list.head = bucket1;
        bucket1.setNext(bucket2);
        bucket2.setNext(bucket3);

        list.insertBefore(bucket2);

        // Expected output: 1 -> 2 -> 2 -> 3
        Bucket current = list.head;
        while (current != null) {
            System.out.print(current.getValue() + " -> ");
            current = current.getNext();
        }
        System.out.println("null");
    }
}
