import java.util.Arrays;

public class ArrayComparator {
    private byte[] internalArray;

    public ArrayComparator(byte[] internalArray) {
        this.internalArray = internalArray;
    }

    /** 
     * Returns true if the contents of the internal array and the provided array match.
     */
    public boolean equals(final byte[] data, int offset, final int len) {
        if (data == null || len < 0 || offset < 0 || offset + len > data.length) {
            return false;
        }
        if (internalArray == null) {
            return len == 0;
        }
        if (internalArray.length != len) {
            return false;
        }
        for (int i = 0; i < len; i++) {
            if (internalArray[i] != data[offset + i]) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        ArrayComparator comparator = new ArrayComparator(new byte[]{1, 2, 3});
        System.out.println(comparator.equals(new byte[]{0, 1, 2, 3}, 1, 3)); // true
        System.out.println(comparator.equals(new byte[]{1, 2, 4}, 0, 3)); // false
    }
}
