import java.util.Properties;

public class VariableSubstitution {

    public static String findAndSubst(String key, Properties props) {
        String value = props.getProperty(key);
        if (value == null) {
            return null;
        }
        // Simple variable substitution logic, assuming variables are in the form ${varName}
        for (String propKey : props.stringPropertyNames()) {
            String propValue = props.getProperty(propKey);
            value = value.replaceAll("\\$\\{" + propKey + "\\}", propValue);
        }
        return value;
    }

    public static void main(String[] args) {
        Properties props = new Properties();
        props.setProperty("greeting", "Hello");
        props.setProperty("name", "World");
        props.setProperty("message", "${greeting}, ${name}!");

        String result = findAndSubst("message", props);
        System.out.println(result); // Output: Hello, World!
    }
}
