import java.net.URI;
import java.net.URISyntaxException;
import java.util.ArrayList;
import java.util.List;

public class PathSegmentImpl {
    private String path;

    public PathSegmentImpl(String path) {
        this.path = path;
    }

    public String getPath() {
        return path;
    }

    @Override
    public String toString() {
        return path;
    }

    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        String path = u.getRawPath();
        if (path == null || path.isEmpty()) {
            return pathSegments;
        }
        if (path.startsWith("/")) {
            path = path.substring(1);
        }
        String[] segments = path.split("/");
        for (String segment : segments) {
            if (decode) {
                try {
                    segment = java.net.URLDecoder.decode(segment, "UTF-8");
                } catch (Exception e) {
                    // Handle exception if necessary
                }
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }
        return pathSegments;
    }

    public static void main(String[] args) {
        try {
            URI uri = new URI("http://example.com/path/to/resource");
            List<PathSegmentImpl> segments = decodePath(uri, true);
            for (PathSegmentImpl segment : segments) {
                System.out.println(segment);
            }
        } catch (URISyntaxException e) {
            e.printStackTrace();
        }
    }
}
