import java.io.File;
import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.util.Iterator;

public class FileIterator implements Iterator<InputStream> {
    private final File[] files;
    private int index = 0;

    public FileIterator(File directory) {
        if (directory == null || !directory.isDirectory()) {
            throw new IllegalArgumentException("Provided directory is null or not a directory");
        }
        this.files = directory.listFiles();
    }

    @Override
    public boolean hasNext() {
        return files != null && index < files.length;
    }

    @Override
    public InputStream next() throws IOException {
        if (!hasNext()) {
            return null;
        }
        File file = files[index++];
        try {
            return new FileInputStream(file);
        } catch (FileNotFoundException e) {
            throw new IOException("File not found: " + file.getAbsolutePath(), e);
        }
    }

    public static void main(String[] args) {
        // Example usage
        File directory = new File("path/to/directory");
        FileIterator iterator = new FileIterator(directory);
        try {
            InputStream inputStream;
            while ((inputStream = iterator.next()) != null) {
                // Process the inputStream
                inputStream.close();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
