import java.io.IOException;
import java.io.InputStream;

public class VarintReader {
    private final InputStream input;

    public VarintReader(InputStream input) {
        this.input = input;
    }

    public long readRawVarint64() throws IOException {
        long result = 0;
        for (int shift = 0; shift < 64; shift += 7) {
            int b = input.read();
            if (b == -1) {
                throw new IOException("Unexpected end of stream");
            }
            result |= (long) (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                return result;
            }
        }
        throw new IOException("Malformed varint");
    }

    public static void main(String[] args) {
        // Example usage
        byte[] varintBytes = {0x96, 0x01}; // Example varint encoding for the number 150
        VarintReader reader = new VarintReader(new java.io.ByteArrayInputStream(varintBytes));
        try {
            long value = reader.readRawVarint64();
            System.out.println("Read value: " + value);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
