import java.io.DataOutput;
import java.io.IOException;

public class BufferWriter {

    /**
     * Writes the contents of the  {@link LinkedBuffer} into the {@link DataOutput}.
     * @return the total content size of the buffer.
     */
    public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
        int totalSize = 0;
        while (node != null) {
            int size = node.start;
            out.write(node.buffer, 0, size);
            totalSize += size;
            node = node.next;
        }
        return totalSize;
    }

    // Assuming LinkedBuffer is defined as follows for completeness
    public static class LinkedBuffer {
        public final byte[] buffer;
        public int start;
        public LinkedBuffer next;

        public LinkedBuffer(int size) {
            this.buffer = new byte[size];
            this.start = 0;
            this.next = null;
        }
    }

    public static void main(String[] args) throws IOException {
        // Example usage
        LinkedBuffer buffer = new LinkedBuffer(10);
        buffer.start = 5; // Simulate writing 5 bytes
        System.arraycopy("Hello".getBytes(), 0, buffer.buffer, 0, 5);

        DataOutput out = new java.io.DataOutputStream(new java.io.ByteArrayOutputStream());
        int size = writeTo(out, buffer);
        System.out.println("Total content size: " + size);
    }
}
