import java.util.ArrayList;
import java.util.List;

class Category {
    private String name;
    private boolean isActive;
    private List<Category> children;

    public Category(String name, boolean isActive) {
        this.name = name;
        this.isActive = isActive;
        this.children = new ArrayList<>();
    }

    public boolean isActive() {
        return isActive;
    }

    public List<Category> getChildren() {
        return children;
    }

    public void addChild(Category child) {
        this.children.add(child);
    }

    public void removeChild(Category child) {
        this.children.remove(child);
    }
}

public class CategoryTree {
    private Category root;

    public CategoryTree(Category root) {
        this.root = root;
    }

    protected int removeUnusedNodes() {
        return removeUnusedNodes(root);
    }

    private int removeUnusedNodes(Category node) {
        int removedCount = 0;
        List<Category> toRemove = new ArrayList<>();

        for (Category child : node.getChildren()) {
            if (!child.isActive()) {
                toRemove.add(child);
                removedCount++;
            } else {
                removedCount += removeUnusedNodes(child);
            }
        }

        for (Category child : toRemove) {
            node.removeChild(child);
        }

        return removedCount;
    }

    public static void main(String[] args) {
        Category root = new Category("Root", true);
        Category child1 = new Category("Child1", false);
        Category child2 = new Category("Child2", true);
        Category child3 = new Category("Child3", false);
        Category child4 = new Category("Child4", true);

        root.addChild(child1);
        root.addChild(child2);
        root.addChild(child3);
        child2.addChild(child4);

        CategoryTree tree = new CategoryTree(root);
        int removed = tree.removeUnusedNodes();
        System.out.println("Removed nodes: " + removed);
    }
}
