import java.util.Enumeration;

public class LoggerAppender {

    private Logger logger;

    public LoggerAppender(Logger logger) {
        this.logger = logger;
    }

    public int appendLoopOnAppenders(LoggingEvent event) {
        int appendCount = 0;
        Enumeration<?> appenders = logger.getAllAppenders();
        while (appenders.hasMoreElements()) {
            Appender appender = (Appender) appenders.nextElement();
            appender.doAppend(event);
            appendCount++;
        }
        return appendCount;
    }

    public static void main(String[] args) {
        Logger logger = Logger.getLogger(LoggerAppender.class);
        LoggerAppender loggerAppender = new LoggerAppender(logger);
        LoggingEvent event = new LoggingEvent("LoggerAppender", logger, org.apache.log4j.Level.INFO, "Test message", null);
        int count = loggerAppender.appendLoopOnAppenders(event);
        System.out.println("Appended to " + count + " appenders.");
    }
}
