    }

    public static void main(String[] args) {
        int[][] matrix = {
            {0, 0, 3, 0},
            {4, 0, 0, 0},
            {0, 0, 0, 0},
            {0, 5, 0, 7}
        };
        SparseMatrix sparseMatrix = new SparseMatrix(matrix);
        System.out.println(sparseMatrix.nonZeros(0)); // Output: 1
        System.out.println(sparseMatrix.nonZeros(1)); // Output: 1
        System.out.println(sparseMatrix.nonZeros(2)); // Output: 0
        System.out.println(sparseMatrix.nonZeros(3)); // Output: 2
