import java.util.List;
import java.util.Set;

public class BucketReloader {

    private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
        Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
        Set<Integer> zeroLabelBucket = bucketsByLabel.get(0);

        for (Integer vertex : minLabelBucket) {
            zeroLabelBucket.add(vertex);
            labels.set(vertex, 0);
        }

        minLabelBucket.clear();
    }

    public static void main(String[] args) {
        // Example usage
        List<Set<Integer>> bucketsByLabel = List.of(
            new HashSet<>(Set.of()), // Bucket 0
            new HashSet<>(Set.of(1, 2, 3)), // Bucket 1
            new HashSet<>(Set.of(4, 5)) // Bucket 2
        );
        List<Integer> labels = List.of(0, 1, 1, 1, 2, 2);

        BucketReloader reloader = new BucketReloader();
        reloader.reload(bucketsByLabel, labels, 1);

