import java.util.Set;
import java.util.HashSet;

public class GraphIterator implements Iterator<Vertex> {
    private Set<Vertex> visited;
    private Set<Vertex> allVertices;

    public GraphIterator(Set<Vertex> vertices) {
        this.allVertices = vertices;
        this.visited = new HashSet<>();
    }

    @Override
    public boolean hasNext() {
        return allVertices.size() > visited.size();
    }

    @Override
    public Vertex next() {
        for (Vertex vertex : allVertices) {
            if (!visited.contains(vertex)) {
                visited.add(vertex);
                return vertex;
            }
        }
        throw new NoSuchElementException();
    }

    // Assuming Vertex is a simple class representing a graph vertex
    public static class Vertex {
        private int id;

        public Vertex(int id) {
            this.id = id;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Vertex vertex = (Vertex) o;
            return id == vertex.id;
        }

        @Override
        public int hashCode() {
            return id;
        }
    }

    public static void main(String[] args) {
        Set<Vertex> vertices = new HashSet<>();
        vertices.add(new Vertex(1));
        vertices.add(new Vertex(2));
        vertices.add(new Vertex(3));

        GraphIterator iterator = new GraphIterator(vertices);
        while (iterator.hasNext()) {
            System.out.println(iterator.next().id);
