import java.util.NoSuchElementException;

class ListNodeImpl<E> {
    E item;
    ListNodeImpl<E> next;
    ListNodeImpl<E> prev;

    ListNodeImpl(ListNodeImpl<E> prev, E element, ListNodeImpl<E> next) {
        this.item = element;
        this.next = next;
        this.prev = prev;
    }
}

public class LinkedListImpl<E> {
    private ListNodeImpl<E> first;
    private ListNodeImpl<E> last;
    private int size;

    private boolean unlink(ListNodeImpl<E> node) {
        if (node == null) {
            return false;
        }

        E element = node.item;
        ListNodeImpl<E> next = node.next;
        ListNodeImpl<E> prev = node.prev;

        if (prev == null) {
            first = next;
        } else {
            prev.next = next;
            node.prev = null;
        }

        if (next == null) {
            last = prev;
        } else {
            next.prev = prev;
            node.next = null;
        }

        node.item = null;
        size--;
        return true;
    }

    public static void main(String[] args) {
        LinkedListImpl<String> list = new LinkedListImpl<>();
        ListNodeImpl<String> node1 = new ListNodeImpl<>(null, "A", null);
        ListNodeImpl<String> node2 = new ListNodeImpl<>(node1, "B", null);
        node1.next = node2;
        list.first = node1;
        list.last = node2;
        list.size = 2;

        boolean result = list.unlink(node2);
        System.out.println("Node removed: " + result); // Should print: Node removed: true
        System.out.println("List size: " + list.size); // Should print: List size: 1
    }
}
