            return str;
        }

        int i = 0;
        while (i < str.length() && str.charAt(i) == leadingCharacter) {
            i++;
        }

        return str.substring(i);
    }

    public static void main(String[] args) {
        System.out.println(trimLeadingCharacter("aaaHelloWorld", 'a')); // Output: HelloWorld
        System.out.println(trimLeadingCharacter("HelloWorld", 'a'));    // Output: HelloWorld
        System.out.println(trimLeadingCharacter("aaa", 'a'));           // Output: (empty string)
        System.out.println(trimLeadingCharacter("", 'a'));              // Output: (empty string)
        System.out.println(trimLeadingCharacter(null, 'a'));            // Output: null
