import java.util.concurrent.locks.ReentrantLock;

class ListNode<E> {
    E item;
    ListNode<E> next;
    ListNode<E> prev;

    ListNode(ListNode<E> prev, E element, ListNode<E> next) {
        this.item = element;
        this.next = next;
        this.prev = prev;
    }
}

class DoublyLinkedList<E> {
    private ListNode<E> first;
    private ListNode<E> last;
    private final ReentrantLock lock = new ReentrantLock();

    private void addListNode(ListNode<E> node) {
        lock.lock();
        try {
            if (last == null) {
                first = last = node;
            } else {
                last.next = node;
                node.prev = last;
                last = node;
            }
        } finally {
            lock.unlock();
        }
    }

    private void removeListNode(ListNode<E> node) {
        lock.lock();
        try {
            ListNode<E> next = node.next;
            ListNode<E> prev = node.prev;

            if (prev == null) {
                first = next;
            } else {
                prev.next = next;
                node.prev = null;
            }

            if (next == null) {
                last = prev;
            } else {
                next.prev = prev;
                node.next = null;
            }
        } finally {
            lock.unlock();
        }
    }

    private void moveAllListNodes(DoublyLinkedList<E> list) {
        lock.lock();
        list.lock.lock();
        try {
            ListNode<E> current = list.first;
            while (current != null) {
                ListNode<E> next = current.next;
                list.removeListNode(current);
                addListNode(current);
                current = next;
            }
            list.first = list.last = null;
        } finally {
            list.lock.unlock();
            lock.unlock();
        }
    }
}
