import java.nio.file.Path;
import java.nio.file.Paths;

public class PathUtil {
    /** 
     * Apply the given relative path to the given path, assuming standard Java folder separation (i.e. "/" separators).
     * @param path the path to start from (usually a full file path)
     * @param relativePath the relative path to apply(relative to the full file path above)
     * @return the full file path that results from applying the relative path
     */
    public static String applyRelativePath(String path, String relativePath) {
        Path basePath = Paths.get(path);
        Path resolvedPath = basePath.resolve(relativePath);
        return resolvedPath.toString();
    }

    public static void main(String[] args) {
        // Example usage
        String path = "/home/user/documents";
        String relativePath = "../pictures/vacation";
        System.out.println(applyRelativePath(path, relativePath)); // Output: /home/user/pictures/vacation
    }
}
