        CacheUtil cacheUtil = new CacheUtil();
        long currentTime = System.currentTimeMillis();
        long lastUpdateTime = currentTime - TimeUnit.MINUTES.toMillis(10);
        long expiredThreshold = TimeUnit.MINUTES.toMillis(5);

        boolean isExpired = cacheUtil.isExpired(currentTime, lastUpdateTime, expiredThreshold);
        System.out.println("Is the cache expired? " + isExpired);
    }
}
