import java.io.IOException;
import java.io.InputStream;

public class ProtocolMessageParser {
    private InputStream input;

    public ProtocolMessageParser(InputStream input) {
        this.input = input;
    }

    public int readTag() throws IOException {
        int firstByte = input.read();
        if (firstByte == -1) {
            return 0; // End of file
        }
        if ((firstByte & 0x80) == 0) {
            return firstByte; // Single byte tag
        }
        int result = firstByte & 0x7F;
        int shift = 7;
        while (true) {
            int b = input.read();
            if (b == -1) {
                throw new IOException("Unexpected end of stream");
            }
            result |= (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                break;
            }
            shift += 7;
            if (shift >= 32) {
                throw new IOException("Malformed tag");
            }
        }
        return result;
    }

    public static void main(String[] args) {
        // Example usage
        byte[] testData = {0x08, (byte) 0x80, 0x02, 0x01};
        ProtocolMessageParser parser = new ProtocolMessageParser(new java.io.ByteArrayInputStream(testData));
        try {
            System.out.println(parser.readTag()); // Should print 8
            System.out.println(parser.readTag()); // Should print 130
            System.out.println(parser.readTag()); // Should print 1
            System.out.println(parser.readTag()); // Should print 0 (EOF)
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
